Main {
    Q = A(U);
    vec4 n = A(U+vec2(0,1));
    vec4 e = A(U+vec2(1,0));
    vec4 s = A(U-vec2(0,1));
    vec4 w = A(U-vec2(1,0));
    vec2 d = vec2(e.x-w.x,n.x-s.x);
    vec3 no = normalize(vec3(d,.1));
    no += .25*(hash(vec4(U,iTime,iFrame)).xyz*2.-1.);
    Q = .2*vec4(1,2,4,4)*exp(-1.*max(dot(no,normalize(vec3(1))),0.));
    Q += .2*vec4(2,2,1,1)*exp(-15.*max(1.-dot(no,normalize(vec3(-1,1,1))),0.));
    Q += .2*vec4(5,3,2,1)*exp(-15.*max(1.-dot(no,normalize(vec3(1,-1,1))),0.));
    Q = .1*Q+.9*B(U);
}
